#!/bin/sh
# Runs the Loot editions parity fixture (loot_composer editions_tests.cairo, generated by
# scripts/editions_cases.mjs) one batch per invocation of scripts/cairo_run.sh (lock + memory
# watchdog) and collects the ED lines in $1; check them with scripts/editions_parity.mjs.
# $2 $3: first and last batch (default 0 23).
#   sh scripts/editions_parity_cairo.sh /path/ed.txt && node scripts/editions_parity.mjs /path/ed.txt
here=$(cd "$(dirname "$0")" && pwd)
out=${1:?out file}; first=${2:-0}; last=${3:-23}
: > "$out"
for i in $(seq -f %02g "$first" "$last"); do
  log="${TMPDIR:-/tmp}/loot_editions_batch_$i.txt"
  (cd "$here/.." && sh scripts/cairo_run.sh scarb test -p loot_composer -- "editions_parity_$i" --include-ignored --no-default-features --features editions_fx) > "$log" 2>&1
  code=$?
  grep "^ED " "$log" >> "$out"
  gas=$(grep -o "l2_gas: ~[0-9]*" "$log" | head -1)
  echo "batch $i: $(grep -c "^ED " "$log") cases, $gas, $(grep -o 'peak [0-9]* MB' "$log"), exit $code"
  [ $code -ne 0 ] && { grep -E "panicked|error|Failure|0x" "$log" | head -5; exit 1; }
done
echo "done: $(grep -c "^ED " "$out") cases in $out"
